@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));
/* Margin notes are for readers with a cursor; a touch device has no room for
   them and no pointer to aim. */
@custom-variant pointer-fine (@media (pointer: fine));

/* ---------------------------------------------------------------------------
   Tokens. A neutral zinc system — no chromatic accent. Colour appears only
   where it carries meaning (links, status). `--line` is the hairline the
   whole frame is drawn with: the border colour, softened toward the
   background so a full-bleed rule reads as structure rather than a box.
--------------------------------------------------------------------------- */

:root {
  color-scheme: light;

  --background: oklch(1 0 0);
  --foreground: oklch(0.141 0.005 285.823); /* zinc-950 */

  --primary: oklch(0.141 0.005 285.823);
  --primary-foreground: oklch(0.985 0 0);

  --secondary: oklch(0.967 0.001 286.375); /* zinc-100 */
  --secondary-foreground: oklch(0.141 0.005 285.823);

  --muted: oklch(0.967 0.001 286.375); /* zinc-100 — a surface */
  --muted-foreground: oklch(0.552 0.016 285.938); /* zinc-500 */

  --card: oklch(1 0 0);
  --card-foreground: oklch(0.141 0.005 285.823);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.141 0.005 285.823);

  --accent: oklch(0.967 0.001 286.375); /* zinc-100 */
  --accent-muted: color-mix(in oklab, var(--accent) 50%, transparent);
  --accent-foreground: oklch(0.21 0.006 285.885);

  --border: oklch(0.92 0.004 286.32); /* zinc-200 */
  --line: color-mix(in oklab, var(--border) 64%, var(--background));
  --input: oklch(0.92 0.004 286.32);
  --ring: oklch(0.705 0.015 286.067); /* zinc-400 */

  --info: oklch(0.67 0.17 244.98);
  --success: oklch(0.723 0.219 149.579);
  --destructive: oklch(0.577 0.245 27.325);
  --link: oklch(0.488 0.243 264.376); /* blue-700 */

  --surface: oklch(0.985 0 0);
  --surface-foreground: oklch(0.141 0.005 285.823);

  --code: var(--background);
  --code-foreground: var(--foreground);
  --code-number: oklch(0.24 0.01 0 / 0.3);
  --code-highlight: oklch(0.49 0.18 257.61 / 0.06);

  --selection: oklch(0.141 0.005 285.823);
  --selection-foreground: oklch(0.985 0 0);

  --header-height: --spacing(14);
  --fade-bottom-height: --spacing(24);
}

.dark {
  color-scheme: dark;

  --background: oklch(0.141 0.005 285.823);
  --foreground: oklch(0.985 0 0);

  --primary: oklch(0.985 0 0);
  --primary-foreground: oklch(0.141 0.005 285.823);

  --secondary: oklch(0.274 0.006 286.033); /* zinc-800 */
  --secondary-foreground: oklch(0.985 0 0);

  --muted: oklch(0.274 0.006 286.033);
  --muted-foreground: oklch(0.705 0.015 286.067); /* zinc-400 */

  --card: oklch(0.21 0.006 285.885); /* zinc-900 */
  --card-foreground: oklch(0.985 0 0);

  --popover: oklch(0.21 0.006 285.885);
  --popover-foreground: oklch(0.985 0 0);

  --accent: oklch(0.274 0.006 286.033);
  --accent-muted: color-mix(in oklab, var(--accent) 20%, transparent);
  --accent-foreground: oklch(0.985 0 0);

  --border: oklch(0.274 0.006 286.033);
  --input: lab(100% 0 0 / 0.15);
  --ring: oklch(0.552 0.016 285.938);

  --success: oklch(0.723 0.219 149.579);
  --destructive: oklch(0.505 0.213 27.518);
  --link: oklch(0.623 0.214 259.815); /* blue-500 */

  --surface: oklch(0.21 0.006 285.885);
  --surface-foreground: oklch(0.985 0 0);

  --code-number: oklch(0.43 0 0);
  --code-highlight: oklch(0.71 0.24 42.36 / 0.06);

  --selection: oklch(0.985 0 0);
  --selection-foreground: oklch(0.141 0.005 285.823);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);

  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);

  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);

  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);

  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);

  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);

  --color-accent: var(--accent);
  --color-accent-muted: var(--accent-muted);
  --color-accent-foreground: var(--accent-foreground);

  --color-border: var(--border);
  --color-line: var(--line);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --color-info: var(--info);
  --color-success: var(--success);
  --color-destructive: var(--destructive);
  --color-link: var(--link);

  --color-surface: var(--surface);
  --color-surface-foreground: var(--surface-foreground);

  --color-code: var(--code);
  --color-code-foreground: var(--code-foreground);
  --color-code-number: var(--code-number);
  --color-code-highlight: var(--code-highlight);

  --color-selection: var(--selection);
  --color-selection-foreground: var(--selection-foreground);

  --font-sans: var(--font-geist-sans), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, SFMono-Regular, monospace;
  --font-heading: var(--font-sans);
  --font-serif: var(--font-plex-serif), ui-serif, Georgia, serif;
  --font-handwriting: var(--font-caveat), var(--font-sans);

  --default-mono-font-feature-settings: "ss11" 1, "zero" 1, "tnum" 1;

  --ease-out-quint: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-io: cubic-bezier(0.65, 0, 0.35, 1);
}

/* ---------------------------------------------------------------------------
   Utilities. The frame system: hairlines that span the viewport rather than
   stopping at the content rail, and diagonal hatching for the gaps between
   panels.
--------------------------------------------------------------------------- */

@utility link {
  @apply decoration-1 underline-offset-3 hover:underline;
}

@utility link-underline {
  @apply underline decoration-current/30 decoration-1 underline-offset-3 transition-colors hover:decoration-current;
}

@utility screen-line-top {
  @apply relative;

  &:before {
    content: "";
    @apply absolute top-0 left-[-100vw] -z-1 h-px w-[200vw] bg-line;
  }
}

@utility screen-line-bottom {
  @apply relative;

  &:after {
    content: "";
    @apply absolute bottom-0 left-[-100vw] -z-1 h-px w-[200vw] bg-line;
  }
}

@utility screen-dashed-line-top {
  @apply screen-line-top;

  &:before {
    content: "";
    @apply bg-inherit bg-[linear-gradient(to_right,var(--line)_4px,transparent_2px)] bg-size-[6px_1px] bg-repeat-x;
  }
}

@utility screen-dashed-line-bottom {
  @apply screen-line-bottom;

  &:after {
    content: "";
    @apply bg-inherit bg-[linear-gradient(to_right,var(--line)_4px,transparent_2px)] bg-size-[6px_1px] bg-repeat-x;
  }
}

@utility screen-line-top-none {
  @apply before:content-none;
}

@utility screen-line-bottom-none {
  @apply after:content-none;
}

/*
 * The hero's floor lattice, continued past the content rail as a whisper. Same
 * 30 degree axes as `FloorLattice`, at the pitch the plate renders it at, so
 * the outer field reads as the same drawing running on rather than as a second
 * texture laid beside it.
 */
@utility hero-lattice {
  /* Light's hairline is a whisper against a near-white ground and needs more
     of itself to survive out here at all; dark's has contrast to spare and
     turns to noise at the same alpha. Two numbers, one drawing. */
  --lattice-alpha: 48%;
  @variant dark {
    --lattice-alpha: 28%;
  }
  --pattern-foreground: color-mix(
    in oklab,
    var(--color-line) var(--lattice-alpha),
    transparent
  );
  background-image:
    repeating-linear-gradient(
      30deg,
      var(--pattern-foreground) 0 1px,
      transparent 1px 27px
    ),
    repeating-linear-gradient(
      150deg,
      var(--pattern-foreground) 0 1px,
      transparent 1px 27px
    );
}
@utility diagonal-stripes {
  @apply [--pattern-foreground:var(--color-line)]/56;
  @apply bg-[repeating-linear-gradient(315deg,var(--pattern-foreground)_0,var(--pattern-foreground)_1px,transparent_0,transparent_50%)] bg-size-[10px_10px];
}

@utility stripe-divider {
  @apply relative h-8;

  &:before {
    content: "";
    @apply absolute left-[-100vw] -z-1 h-full w-[200vw] diagonal-stripes;
  }
}

/* Pointer-coarse devices get a 24px-minimum hit area without a 24px box. */
@utility extend-touch-target {
  @media (pointer: coarse) {
    @apply relative touch-manipulation after:absolute after:-inset-2;
  }
}

/* ---------------------------------------------------------------------------
   Base
--------------------------------------------------------------------------- */

@layer base {
  *,
  ::after,
  ::before,
  ::backdrop,
  ::file-selector-button {
    @apply border-border outline-ring/50;
  }

  html {
    -webkit-text-size-adjust: 100%;
    scroll-behavior: smooth;
  }

  body {
    @apply bg-background text-foreground antialiased;
    font-synthesis-weight: none;
    text-rendering: optimizeLegibility;
  }

  ::selection {
    @apply bg-selection text-selection-foreground;
  }

  /* Suppress every transition until after first paint so the stored theme
     never animates in from the wrong colour. */
  .preload *,
  .preload *::before,
  .preload *::after {
    transition: none !important;
    animation: none !important;
  }

  ::-webkit-scrollbar {
    width: 5px;
    height: 5px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: var(--border);
    border-radius: 5px;
  }
  * {
    scrollbar-width: thin;
    scrollbar-color: var(--border) transparent;
  }

  [id] {
    @apply scroll-mt-18;
  }

  /* One focus ring for the whole site. Every keyboard affordance — header
     buttons, palette rows, inline links, the mosaic — draws the same 2px
     outline at the same offset, so focus never changes shape as it moves.
     Components that need a different shape opt out with their own `outline`,
     not with their own ring colour. */
  :focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
}

/* ---------------------------------------------------------------------------
   Chrome
--------------------------------------------------------------------------- */

.skip-link {
  position: fixed;
  top: 0.75rem;
  left: 50%;
  z-index: 90;
  translate: -50% -300%;
  padding: 0.5rem 0.875rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--background);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  transition: translate 200ms var(--ease-out-quint);
}
.skip-link:focus-visible {
.skip-link:focus-visible {
  translate: -50% 0;
}

/* ---------------------------------------------------------------------------
   Typeset — the two long-form measures. `--typeset-flow` is the vertical
   rhythm between blocks, expressed in the block's own em so it scales with
   the measure rather than the root.
--------------------------------------------------------------------------- */

.typeset {
  --typeset-size: 1rem;
  --typeset-leading: 1.65;
  --typeset-flow: 1.25em;

  font-size: var(--typeset-size);
  line-height: var(--typeset-leading);
  text-wrap: pretty;
}

.typeset > * + * {
  margin-top: var(--typeset-flow);
}

.typeset-description {
  --typeset-size: 15px;
  --typeset-leading: 1.6;
  --typeset-flow: 1em;
}

.typeset-timescale {
  --typeset-size: 0.875rem;
  --typeset-leading: 1.5;
  --typeset-flow: 1em;
}

/* ---------------------------------------------------------------------------
   Entrance. The frame is drawn instantly; only the mosaic and the palette
   fade, and neither loops.
--------------------------------------------------------------------------- */

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* ---------------------------------------------------------------------------
   Activity mosaic. Fixed 12px blocks on a 2px gutter, square corners — the
   grid is a measuring instrument, so its cells are not decorated. Intensity
   is carried by the neutral foreground at five opacities.
--------------------------------------------------------------------------- */

.activity-grid {
  --cell-size: 12px;
  --cell-gap: 2px;
  display: grid;
  grid-template-columns: repeat(var(--weeks, 53), var(--cell-size));
  gap: var(--cell-gap);
  width: max-content;
  /* The grid is one tab stop, but the thing that moves is the active cell, so
     the ring is drawn there instead of around all 365 of them. */
  outline: none;
  /* Room for that ring and for the live cell's 2px halo, so neither can cross
     the panel's vertical rail. */
  padding-inline: 3px;
}

.activity-col {
  position: relative;
  display: grid;
  grid-template-rows: repeat(7, var(--cell-size));
  gap: var(--cell-gap);
  padding-top: 1.05rem;
}

/* Sits above its own column, allowed to overflow it. */
.activity-month {
  position: absolute;
  top: 0;
  left: 0;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  line-height: 1;
  color: var(--muted-foreground);
  white-space: nowrap;
  pointer-events: none;
}

/* The strip is 742px of year on a 372px phone, so it is dragged rather than
   trimmed. The edge fades are driven by the scroll position itself: each side
   is masked only while there is more grid past it, so a strip that fits shows
   no fade at all and a strip scrolled to its end stops advertising an end. */
@property --activity-fade-s {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}
@property --activity-fade-e {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@keyframes activity-fade-s {
  from {
    --activity-fade-s: 0px;
  }
  to {
    --activity-fade-s: var(--activity-fade);
  }
}
@keyframes activity-fade-e {
  from {
    --activity-fade-e: var(--activity-fade);
  }
  to {
    --activity-fade-e: 0px;
  }
}

.activity-scroll {
  --activity-fade: 2.5rem;
  display: flex;
  /* The same gutter every other row in the panel keeps, so the first and last
     week line up with the caption above them rather than with the rail. */
  padding-inline: 1rem;
  /* Centred while the year fits the rail, flush-left once it does not —
     `safe` is what keeps the first week reachable instead of centring it off
     the scrollable edge. */
  justify-content: safe center;
  overflow-x: auto;
  overflow-y: hidden;
  /* The grid is a drawing; a scrollbar drawn under it would read as part of
     the figure. The strip still scrolls by drag, wheel and keyboard. */
  scrollbar-width: none;
  mask-image: linear-gradient(
    to right,
    transparent 0,
    #000 var(--activity-fade-s),
    #000 calc(100% - var(--activity-fade-e)),
    transparent 100%
  );
  animation:
    activity-fade-s 1ms linear both,
    activity-fade-e 1ms linear both;
  animation-timeline: scroll(self inline), scroll(self inline);
  animation-range:
    0 var(--activity-fade),
    calc(100% - var(--activity-fade)) 100%;
}

.activity-scroll::-webkit-scrollbar {
  display: none;
}

.activity-cell {
  background: color-mix(
    in oklab,
    var(--muted-foreground) var(--level, 10%),
    transparent
  );
  position: relative;
  animation: fade-in 260ms var(--ease-out-quint) both;
  animation-delay: calc(var(--col, 0) * 5ms + 320ms);
  transition:
    outline-color 120ms var(--ease-out-quint),
    background-color 150ms var(--ease-out-quint);
  outline: 1px solid transparent;
  outline-offset: 1px;
}

/* Pointer: a hairline marker. Keyboard: the site's own focus ring, moved onto
   the active descendant so focus keeps the same shape it has everywhere else. */
.activity-cell[data-active="true"] {
  outline-color: var(--foreground);
}

.activity-grid:focus-visible .activity-cell[data-active="true"] {
  outline: 2px solid var(--ring);
  outline-offset: 1px;
}

/* A day the feed never reported is not a day of no work. Measured zero is a
   faint filled square; unreported is an empty frame — so a stalled feed is
   legible in the drawing itself and not only in the caption under it. */
.activity-cell[data-recorded="false"] {
  background: transparent;
  box-shadow: inset 0 0 0 1px
    color-mix(in oklab, var(--muted-foreground) 16%, transparent);
}

/* Today is a ring, never a fill — a projection must not read as a record. */
.activity-cell[data-live="true"]::after {
  content: "";
  position: absolute;
  inset: -2px;
  border: 1px solid var(--muted-foreground);
}

/* ---------------------------------------------------------------------------
   A single sweep of light across a line of text, once, on load. The gradient
   is painted into the glyphs themselves and slid from right to left, so the
   highlight travels the line rather than the line changing colour. Spread is
   in `ch` so it scales with the type, and the background is twice the element
   plus two spreads wide so the sweep starts and ends fully off the text.
--------------------------------------------------------------------------- */
@keyframes shimmer-sweep {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: 0 0;
  }
}

.shimmer {
  --shimmer-spread: calc(3ch + 40px);
  --shimmer-angle: 20deg;
  background-image: linear-gradient(
    calc(90deg + var(--shimmer-angle)),
    currentColor calc(50% - var(--shimmer-spread)),
    color-mix(in oklch, var(--foreground), currentColor 50%)
      calc(50% - var(--shimmer-spread) * 0.5),
    var(--foreground) 50%,
    color-mix(in oklch, var(--foreground), currentColor 50%)
      calc(50% + var(--shimmer-spread) * 0.5),
    currentColor calc(50% + var(--shimmer-spread))
  );
  background-repeat: no-repeat;
  background-size: calc(200% + var(--shimmer-spread) * 2) 100%;
  background-position: 0 0;
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: shimmer-sweep 1.5s linear 1;
}

/* Motion is the whole effect, so with it turned off there is nothing left to
   show — paint the text normally rather than leaving it in a frozen gradient. */
@media (prefers-reduced-motion: reduce) {
  .shimmer {
    background-image: none;
    animation: none;
    -webkit-text-fill-color: currentColor;
  }
}

/* ---------------------------------------------------------------------------
   The bottom edge of the sheet. Fixed, so it is the last thing every scroll
   runs into: the page dissolves into the background over six rems, and the
   gradient is itself masked from the top so the fade has no visible start.
   The strip below it is opaque background padded by the home indicator, which
   is what the floating palette dock rests on.
--------------------------------------------------------------------------- */
.fade-bottom {
  position: fixed;
  inset-inline: 0;
  bottom: 0;
  z-index: 50;
  pointer-events: none;
}

.fade-bottom-gradient {
  height: var(--fade-bottom-height);
  background: linear-gradient(to bottom, transparent, var(--background));
  mask-image: linear-gradient(to top, var(--background) 25%, transparent);
  backdrop-filter: blur(1px);
}

.fade-bottom-rest {
  background: var(--background);
  padding-bottom: env(safe-area-inset-bottom, 0px);
}

/* ---------------------------------------------------------------------------
   Figure 404. Drawn from the same cells as the activity grid, at plate scale:
   the page that has no data says so in the site's own word for it. Cells size
   themselves off the column rather than off a fixed pixel, so the plate is the
   full width of the frame at every viewport.
--------------------------------------------------------------------------- */
.glyph-grid {
  display: grid;
  grid-template-columns: repeat(var(--cols), minmax(0, 1fr));
  gap: 2px;
  width: 100%;
}

.glyph-grid > * {
  aspect-ratio: 1;
}

/* ---------------------------------------------------------------------------
   Prose (MDX) — long-form runs on the serif; structure stays sans.
--------------------------------------------------------------------------- */

.prose {
  font-family: var(--font-serif);
  color: var(--foreground);
}
.prose h2,
.prose h3 {
  font-family: var(--font-heading);
  font-weight: 500;
  letter-spacing: -0.01em;
  scroll-margin-top: calc(var(--header-height) + 1rem);
}
.prose h2 {
  font-size: 1.5rem;
  line-height: 1.3;
  margin-top: 2.5em;
}
.prose h3 {
  font-size: 1.25rem;
  line-height: 1.35;
  margin-top: 2em;
}
.prose h2 + *,
.prose h3 + * {
  margin-top: 0.75em;
}
.prose a {
  color: var(--link);
  text-decoration: underline;
  text-decoration-color: color-mix(in oklab, currentColor 30%, transparent);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition: text-decoration-color 150ms var(--ease-out-quint);
}
.prose a:hover {
  text-decoration-color: currentColor;
}
.prose strong {
  font-weight: 600;
}
.prose ul,
.prose ol {
  padding-left: 1.25rem;
}
.prose ul {
  list-style: disc;
}
.prose ol {
  list-style: decimal;
}
.prose li::marker {
  color: var(--muted-foreground);
}
.prose li + li {
  margin-top: 0.5rem;
}
.prose blockquote {
  padding-left: 1.125rem;
  border-left: 2px solid var(--border);
  color: var(--muted-foreground);
  font-style: italic;
}
.prose hr {
  border: 0;
  border-top: 1px solid var(--line);
}
.prose img {
  border: 1px solid var(--line);
}
.prose :not(pre) > code {
  font-family: var(--font-mono);
  font-size: 0.85em;
  background: var(--muted);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 0.1em 0.35em;
}
.prose pre {
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  line-height: 1.6;
  background: var(--code);
  color: var(--code-foreground);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 1rem 1.125rem;
  overflow-x: auto;
}
.prose pre code {
  background: none;
  border: 0;
  padding: 0;
}
.prose .anchor {
  position: absolute;
}

/* sugar-high — four roles, no rainbow */
.prose pre .sh__token--keyword,
.prose pre .sh__token--sign {
  color: var(--link);
}
.prose pre .sh__token--string,
.prose pre .sh__token--property {
  color: var(--muted-foreground);
}
.prose pre .sh__token--comment {
  color: var(--code-number);
}
.prose pre .sh__token--identifier,
.prose pre .sh__token--entity {
  color: var(--foreground);
}

/* ---------------------------------------------------------------------------
   Command palette
--------------------------------------------------------------------------- */

@keyframes palette-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: none;
  }
